import subprocess, re, os, json

# Step 1: files with tasklet_init or DECLARE_TASKLET / tasklet_setup
out = subprocess.run(['grep','-rln','tasklet_init\|tasklet_setup\|DECLARE_TASKLET','--include=*.c','drivers/','net/'], capture_output=True, text=True).stdout.split()
print("files with tasklet defs:", len(out))

results = []
for f in out:
    try:
        src = open(f, errors='ignore').read()
    except: continue
    lines = src.split('\n')
    # find tasklet callback function names
    cb_names = set()
    for i,l in enumerate(lines):
        m = re.search(r'tasklet_(init|setup)\s*\(\s*&?[^,]+,\s*([A-Za-z_0-9]+)', l)
        if m: cb_names.add(m.group(2))
        m = re.search(r'DECLARE_TASKLET[^ (]*\(\s*[^,]+,\s*([A-Za-z_0-9]+)', l)
        if m: cb_names.add(m.group(1))
    if not cb_names: continue
    # find function extents of callbacks
    for cb in cb_names:
        # locate "static void cb(" def
        for i,l in enumerate(lines):
            if re.search(r'\b'+re.escape(cb)+r'\s*\(', l) and not re.search(r'&'+re.escape(cb), l) and 'tasklet_' not in l:
                # crude function extent: until next line that starts with '}' at col 0
                start = i
                end = min(i+200, len(lines)-1)
                for j in range(i, min(i+300, len(lines))):
                    if lines[j].startswith('}'):
                        end = j; break
                body = '\n'.join(lines[start:end+1])
                plain = [(start+k+1) for k,bl in enumerate(body.split('\n')) if re.search(r'spin_lock\s*\(', bl)]
                if plain:
                    results.append((f, cb, start+1, plain))
                break
for r in results:
    print(r)

